import {makeRetry,saveRetry} from './workshop-exam-history.mjs';
import {mountExamHistory} from './workshop-exam-history-ui.mjs';
import {newExam,readExam,examKey,archiveExam,examEvidence,grade,expected,submit,examReady} from './workshop-exam-model.mjs';
import {loadResults,alternate} from './workshop-challenges.mjs';
import {caseInfo} from './workshop-content.mjs';
import {required,sampleTimes,snapshot,correctDiagnosis} from './workshop-model.mjs';
import {initialLanguage} from './i18n.mjs';
import {mountWorkshopBench} from './workshop-bench.mjs';
const $=s=>document.querySelector(s),p=(es,en)=>({es,en}),el=(tag,text,host)=>{const e=document.createElement(tag);e.textContent=text;host.append(e);return e;};
let lang=initialLanguage(),exam=null,time=.5,playing=false,cut=true,last=0,frame=0,error=false,displayedKind=null;try{exam=readExam(localStorage);}catch{}
const t=x=>x[lang],names={mechanics:p('Mecánica','Mechanics'),electronics:p('Electrónica','Electronics'),hydraulics:p('Hidráulica','Hydraulics'),pneumatics:p('Neumática','Pneumatics')},views=new Map();
function options(c){return {...caseInfo[c.kind].options,[alternate[c.kind].answer]:alternate[c.kind].label,combined:p('Ambas causas: suministro/ganancia y defecto principal','Both causes: supply/gain and primary fault'),'intermittent-primary':p('Defecto principal intermitente','Intermittent primary fault'),'intermittent-alternate':p('Suministro/ganancia intermitente','Intermittent supply/gain fault')};}
function labels(c){const o=options(c),primary=caseInfo[c.kind].options[({mechanics:'ground',electronics:'clipping',hydraulics:'leak',pneumatics:'restriction'})[c.kind]],alt=alternate[c.kind].label;o.combined=p(primary.es+' + '+alt.es,primary.en+' + '+alt.en);o['intermittent-primary']=p('Intermitente: '+primary.es,'Intermittent: '+primary.en);o['intermittent-alternate']=p('Intermitente: '+alt.es,'Intermittent: '+alt.en);return o;}
const historyUI=mountExamHistory({lang:()=>lang,busy:()=>Boolean(exam&&!exam.finished),name:kind=>t(names[kind]),faultName:(kind,fault)=>t(labels({kind})[correctDiagnosis({kind,fault})]),review:(original,index)=>{exam=structuredClone(original);exam.index=index;time=.5;playing=false;save();render();$('#exam').scrollIntoView({block:'start'});},retry:(original,index)=>{exam=makeRetry(original,index);time=.5;playing=false;save();render();$('#exam').scrollIntoView({block:'start'});},cancel:()=>{exam=null;playing=false;try{localStorage.removeItem(examKey);}catch{}render();}});
function save(){try{localStorage.setItem(examKey,JSON.stringify(exam));if(exam.finished){if(exam.retryOf)saveRetry(localStorage,exam);else archiveExam(localStorage,exam);}error=false;}catch{error=true;}}
function bench(c){if(!views.has(c.kind)){const node=el('div','',$('#banks'));node.className='case-banks';const hosts=[0,1].map(i=>{const card=el('article','',node);el('h3',i?'B':'A',card);const host=el('div','',card);host.className='workshop-viewport';return host;});const a=mountWorkshopBench(hosts[0],c.kind,'A'),b=mountWorkshopBench(hosts[1],c.kind,'B');if(a&&b){a.onView(v=>b.setView(v));b.onView(v=>a.setView(v));}views.set(c.kind,{node,a,b,hosts});}for(const [kind,v]of views)v.node.hidden=kind!==c.kind;const v=views.get(c.kind);if(displayedKind!==c.kind){v.a?.setCut(cut);v.b?.setCut(cut);displayedKind=c.kind;}return v;}
function reading(m,id){const map={battery:`${m.loaded} V`,ground:`${m.drop} V`,input:`Vin ${m.inputPeak} V · G ${m.gain}`,output:`Vout ${m.outputPeak} V · ±${m.rail} V`,speed:`${m.speed} mm/s`,flow:`${m.inlet} L/min`,leak:`${m.leak} L/min`,supply:`${m.supply} bar`,exhaust:`${m.back} bar`};return map[id];}
function draw(){if(!exam)return;const c=exam.cases[exam.index],v=bench(c);v.a?.draw(snapshot({...c,time},true),time);v.b?.draw(snapshot({...c,time}),time);for(const [i,h]of v.hosts.entries())if(!(i?v.b:v.a))h.textContent=t(p('3D no disponible; las mediciones siguen disponibles.','3D unavailable; measurements remain available.'));$('#examSignal').toggleAttribute('hidden',c.kind!=='electronics');if(c.kind==='electronics')plot(c);$('#time').value=Math.round(time*100);$('#live').textContent='t = '+time.toFixed(2)+' · A '+t(p('sano','healthy'))+' / B '+t(p('caso','case'));$('#play').textContent=t(playing?p('Pausar','Pause'):p('Reproducir','Play'));}
function plot(c){const root=$('#examSignal');root.replaceChildren();root.setAttribute('aria-label',t(p('Salidas A y B, voltios y milisegundos','Outputs A and B, volts and milliseconds')));const svg=(tag,attrs,text)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);for(const [k,v]of Object.entries(attrs))n.setAttribute(k,v);if(text)n.textContent=text;root.append(n);};for(const voltage of [-12,0,12]){svg('line',{x1:40,x2:580,y1:100-voltage*6,y2:100-voltage*6,stroke:'#b5c1aa'});svg('text',{x:0,y:104-voltage*6,fill:'#21392f'},voltage+' V');}for(const [healthy,color,name]of [[true,'#37786e','A'],[false,'#a25b2b','B']]){let path='';for(let i=0;i<=240;i++){const m=snapshot({...c,time:time+i/60},healthy);path+=(i?'L':'M')+(40+i/240*540)+','+(100-m.output*6);}svg('path',{d:path,stroke:color,fill:'none','stroke-width':2});svg('text',{x:healthy?100:400,y:18,fill:color},name+' · Vout');}svg('text',{x:40,y:195,fill:'#21392f'},'0 ms');svg('text',{x:525,y:195,fill:'#21392f'},'40 ms');}
function render(){$('#historyJump').textContent=t(p('Ver historial de exámenes','View exam history'));document.documentElement.lang=lang;$('#language').value=lang;$('#languageLabel').textContent=t(p('Idioma','Language'));$('#back').textContent=t(p('← Resumen y plan de repaso','← Summary and review plan'));$('#back').href='workshop.html?lang='+lang+'#weeklyReview';$('#title').textContent=t(p('Examen semanal · cuatro talleres','Weekly exam · four workshops'));$('#intro').textContent=t(p('Un caso sorpresa por taller. Sin pistas ni corrección durante el examen. Cada caso: 50 puntos por interpretar mediciones y 50 por diagnóstico. Envía una sola respuesta por caso; al terminar se explican los errores y se ajustan los repasos. El examen no cuenta como reparación verificada para tu meta o racha.','One surprise case per workshop. No hints or correctness feedback during the exam. Each case: 50 points for measurement interpretations and 50 for diagnosis. Submit once per case; after finishing, errors are explained and reviews update. The exam does not count as a verified repair toward your goal or streak.'));$('#start').textContent=t(exam&&!exam.finished?p('Abandonar e iniciar otro examen','Abandon and start another exam'):p('Iniciar examen nuevo','Start new exam'));$('#saveStatus').textContent=!exam?t(p('Inicia un examen. Los resultados se guardan en este navegador.','Start an exam. Results are stored in this browser.')):error?t(p('No se pudo guardar. El examen sigue en memoria; vuelve a intentar guardar al terminar.','Could not save. The exam remains in memory; retry saving when finished.')):t(p('Progreso guardado en este navegador. Puedes recargar y continuar.','Progress is saved in this browser. You can reload and resume.'));$('#exam').hidden=!exam;$('#results').replaceChildren();historyUI.render();if(!exam)return;if(exam.retryOf){$('#title').textContent=t(p('Reintento de un caso','Single-case retry'));$('#intro').textContent=t(p('Mismo fallo y mismas condiciones del examen original. Respuestas en blanco, sin pistas hasta enviar. Esta práctica se guarda por separado y no modifica la nota original.','Same fault and conditions as the original exam. Blank answers, no hints until submission. This practice is saved separately and never changes your original score.'));}
const c=exam.cases[exam.index];$('#caseTitle').textContent=(exam.retryOf?'1/1':(exam.index+1)+'/4')+' · '+t(names[c.kind]);$('#status').textContent=t(exam.finished?p('Revisión: respuestas bloqueadas. Selecciona una prueba para sincronizar ambos bancos.','Review: answers are locked. Select a test to synchronise both benches.'):p('Observa, mide y clasifica cada magnitud frente a A. Luego elige la causa.','Observe, measure and classify each quantity against A. Then choose the cause.'));$('#cut').textContent=t(p('Abrir/cerrar corte','Toggle cutaway'));$('#timeLabel').textContent=t(p('Reloj compartido del ensayo','Shared test clock'));$('#limits').textContent=t(caseInfo[c.kind].limit);$('#questions').replaceChildren();
for(const sample of sampleTimes(c))for(const id of required[c.kind]){const field=el('fieldset','',$('#questions'));el('legend',t(caseInfo[c.kind].tests[id])+' · t = '+sample,field);const r=c.readings.find(r=>r.id===id&&r.time===sample);const measure=el('button',t(p('Medir','Measure')),field);measure.dataset.measure=id+':'+sample;measure.onclick=()=>{playing=false;time=sample;const v=bench(c),part=({battery:'battery',ground:'ground',input:'signals',output:'signals',speed:'piston',flow:'flow',leak:'leak',supply:'regulator',exhaust:'silencer'})[id];v.a?.select(part);v.b?.select(part);if(!r&&!exam.finished)c.readings.push({id,time:sample,choice:null});save();render();};if(r||exam.finished){el('p','A: '+reading(snapshot({...c,time:sample},true),id)+' · B: '+reading(snapshot({...c,time:sample}),id),field);for(const value of [false,true]){const b=el('button',t(value?p('Anormal','Abnormal'):p('Normal','Normal')),field);b.dataset.choice=id+':'+sample+':'+value;b.setAttribute('aria-pressed',String(r?.choice===value));b.disabled=Boolean(exam.finished);b.onclick=()=>{r.choice=value;save();render();};}if(exam.finished){const ok=r.choice===expected(c,id,sample);el('p',t(ok?p('Correcto.','Correct.'):p('Error.','Incorrect.'))+' '+t(p('La magnitud indicada ','The named quantity '))+t(expected(c,id,sample)?p('difiere de A.','differs from A.'):p('coincide con A.','matches A.'))+' '+t(p('Compara estos valores, no la velocidad de otra pieza.','Compare these values, not another part’s speed.')),field);}}}
const select=$('#diagnosis');select.replaceChildren();el('option',t(p('Elige una causa','Choose a cause')),select).value='';for(const [id,label]of Object.entries(labels(c)))el('option',t(label),select).value=id;select.value=c.diagnosis;select.disabled=Boolean(exam.finished);$('#diagnosisLabel').textContent=t(p('Diagnóstico','Diagnosis'));$('#submit').textContent=t((exam.retryOf||exam.index===3)?p('Terminar examen','Finish exam'):p('Enviar y continuar','Submit and continue'));if(exam.retryOf)$('#submit').textContent=t(p('Enviar reintento','Submit retry'));$('#submit').disabled=Boolean(exam.finished)||!examReady(c);
if(exam.finished){const total=exam.retryOf?grade(exam.cases[exam.retryIndex]).score:Math.round(exam.cases.reduce((n,c)=>n+grade(c).score,0)/4);el('h2',t(p('Resultado: ','Result: '))+total+'/100',$('#results'));el('p',error?t(p('Resultados aún no guardados: reintenta para actualizar el plan.','Results not saved yet: retry to update the plan.')):t(p('Los errores se añadieron al plan de repaso; tus reparaciones verificadas siguen separadas. Revisa cada caso antes de volver al calendario.','Errors have been added to the review plan; your verified repairs remain separate. Review each case before returning to the calendar.')),$('#results'));for(const [i,entry]of exam.cases.entries()){if(exam.retryOf&&i!==exam.retryIndex)continue;const b=el('button',t(names[entry.kind])+' · '+grade(entry).score+'/100',$('#results'));b.dataset.reviewCase=i;b.onclick=()=>{exam.index=i;time=.5;playing=false;save();render();};}el('p',t(p('Tu diagnóstico: ','Your diagnosis: '))+t(labels(c)[c.diagnosis])+' · '+t(p('Causa del caso: ','Case cause: '))+t(labels(c)[correctDiagnosis(c)]),$('#results'));el('p',t(c.fault==='alternate'?alternate[c.kind].explain:c.fault==='primary'?caseInfo[c.kind].explain:c.fault==='combined'?p('Ambas causas están activas. Cada prueba separa una parte del problema; una única causa no explica todas las diferencias con A.','Both causes are active. Each test isolates part of the problem; a single cause cannot explain all differences from A.'):p('El fallo aparece entre 0,75 y 1,75 de cada período de 2. Una lectura normal en 0,5 no descarta el fallo: compara con 1,25 usando Medir y el cursor.','The fault appears from 0.75 to 1.75 of each 2-unit period. A normal reading at 0.5 does not rule it out: compare with 1.25 using Measure and the cursor.')),$('#results'));const retry=el('button',t(p('Guardar resultados otra vez','Retry saving results')),$('#results'));retry.onclick=()=>{save();render();};}draw();}
$('#language').onchange=e=>{lang=e.target.value;try{localStorage.setItem('mecanica.locale.v1',lang);}catch{}const u=new URL(location.href);u.searchParams.set('lang',lang);history.replaceState(null,'',u);render();};$('#start').onclick=()=>{let rows=[];try{rows=[...loadResults(localStorage),...examEvidence(localStorage)];}catch{}exam=newExam(rows.sort((a,b)=>Date.parse(a.date)-Date.parse(b.date)));time=.5;playing=false;save();render();};$('#diagnosis').onchange=e=>{exam.cases[exam.index].diagnosis=e.target.value;save();render();};$('#submit').onclick=()=>{if(submit(exam)){time=.5;playing=false;save();render();}};$('#time').oninput=e=>{playing=false;time=+e.target.value/100;draw();};$('#cut').onclick=()=>{cut=!cut;const v=bench(exam.cases[exam.index]);v.a?.setCut(cut);v.b?.setCut(cut);draw();};function tick(now){frame=0;if(!playing||document.hidden)return;time=Math.min(7.99,time+(last?Math.min(.05,(now-last)/1000):0)*.5);last=now;draw();if(time>=7.99)playing=false;if(playing)frame=requestAnimationFrame(tick);}$('#play').onclick=()=>{playing=!playing;if(time>=7.99)time=0;last=0;if(playing&&!frame)frame=requestAnimationFrame(tick);draw();};document.addEventListener('visibilitychange',()=>{if(document.hidden)playing=false;});new IntersectionObserver(([e])=>{if(!e.isIntersecting)playing=false;}).observe($('#banks'));matchMedia('(prefers-reduced-motion:reduce)').addEventListener('change',()=>{playing=false;draw();});if(exam?.finished)save();render();
window.examDebug=()=>exam;
